package com.sisge.ms.security;
import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.*; import org.springframework.web.filter.OncePerRequestFilter; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
@Configuration public class SecurityConfig { @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();} @Bean SecurityFilterChain chain(HttpSecurity h,JwtService jwt,UserAuthenticationService users)throws Exception{h.csrf(c->c.disable()).cors(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/v1/auth/login","/actuator/health").permitAll().anyRequest().authenticated()).addFilterBefore(new JwtFilter(jwt,users),UsernamePasswordAuthenticationFilter.class);return h.build();} static class JwtFilter extends OncePerRequestFilter {private final JwtService j;private final UserAuthenticationService u;JwtFilter(JwtService j,UserAuthenticationService u){this.j=j;this.u=u;} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse p,FilterChain c)throws java.io.IOException,ServletException{String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")){String s=j.subject(h.substring(7));if(s!=null){try{var x=u.load(s);var a=new UsernamePasswordAuthenticationToken(x,null,java.util.List.of());org.springframework.security.core.context.SecurityContextHolder.getContext().setAuthentication(a);}catch(org.springframework.security.core.userdetails.UsernameNotFoundException ignored){}}}c.doFilter(r,p);}} }
